import {
    Table,
    BooleanColumn,
    IntegerColumn,
    ReferenceColumn,
    StringColumn,
    TranslatedFieldColumn,
    TranslatedTextColumn,
} from '../../db'

export const sys_ux_app_route = Table({
    actions: {
        read: true,
        update: true,
        delete: true,
        create: true,
    },
    allowClientScripts: false,
    allowNewFields: false,
    allowUiActions: false,
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        no_text_index: true,
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'UX App Route',
    name: 'sys_ux_app_route',
    schema: {
        // Was StringColumn({}). The dictionary entry is translated_field. TranslatedFieldColumn takes
        // the same config and yields the same string value type, so nothing a developer writes changes.
        // Also `mandatory: true` on the instance, ignored for backward compatibility with the Record API.
        name: TranslatedFieldColumn({
            maxLength: 255,
        }),
        app_config: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    label: 'App Configuration',
                    hint: 'App to use this router configuration',
                },
            ],
            maxLength: 32,
            referenceTable: 'sys_ux_app_config',
        }),
        description: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            maxLength: 4000,
        }),
        interoperable: BooleanColumn({
            label: [
                {
                    label: 'Use across experiences',
                    hint: 'Allow other experiences to display the page content for users who have access and meet usage conditions. The variant audiences and conditions for this page will still apply when used in other experiences.',
                },
            ],
            maxLength: 40,
        }),
        // `mandatory: true` on the instance, ignored here for backward compatibility so we don't
        // break apps that create these records through the Record API.
        route_type: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Route',
            maxLength: 255,
        }),
        fields: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            maxLength: 4000,
        }),
        optional_parameters: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            maxLength: 4000,
        }),
        screen_type: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: 'Screen Collection',
            maxLength: 32,
            referenceTable: 'sys_ux_screen_type',
        }),
        extension_point: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Extension point to use this router configuration',
                    label: 'Extension Point',
                    plural: 'Extension Points',
                },
            ],
            maxLength: 32,
            referenceTable: 'sys_ux_extension_point',
        }),
        icon: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Icon',
            maxLength: 255,
        }),
        order: IntegerColumn({
            default: '0',
            label: [
                {
                    hint: 'Order of routes when used in navigational constructs such as tab lists',
                    label: 'Order',
                    plural: 'Orders',
                },
            ],
            maxLength: 40,
        }),
        parent_macroponent: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: [
                {
                    hint: 'Macroponent to use this router configuration',
                    label: 'Parent Macroponent',
                    plural: 'Parent Macroponents',
                },
            ],
            maxLength: 32,
            referenceTable: 'sys_ux_macroponent',
        }),
        parent_macroponent_composition_element_id: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'The element ID of the composition node in the parent element that will render this route',
                    label: 'Parent Macroponent Composition Element ID',
                    plural: 'Parent Macroponent Composition Element IDs',
                },
            ],
            maxLength: 64,
        }),
    },
    textIndex: true,
})
